describe('user form', () => {
  it('fills, submits, and checks the form', () => {
    cy.visit('/users/new')
    cy.get('[data-testid="first-name"]')
      .type('Johnny')
      .should('have.value', 'Johnny')
    cy.get('[data-testid="last-name"]').type('Appleseed')
    cy.get('form').submit()
  })
})

describe('users', () => {
  beforeEach(() => {
    cy.intercept('GET', '/api/users', { fixture: 'users.json' }).as('getUsers')
  })

  it('shows deterministic user data', () => {
    cy.visit('/users')
    cy.wait('@getUsers')
    cy.contains('Ada Lovelace').should('be.visible')
  })
})

describe('checkout', () => {
  it('submits an order', () => {
    cy.visit('/checkout')
    cy.get('[data-cy=submit]').click()
    cy.debug()
    cy.contains('Order confirmed').should('be.visible')
  })
})
